// IdentityAdminServiceServer is the server API for IdentityAdminService service.
// All implementations must embed UnimplementedIdentityAdminServiceServer
// for forward compatibility.
//
// IdentityAdminService changes identity state. It serves the admin CLI over
// mTLS and site-admins through the gateway; everyone else gets
// PermissionDenied. The calls marked self-service act on the calling user
// and are open to any signed-in user.
type IdentityAdminServiceServer interface {
	// EnableUser re-enables a user.
	EnableUser(context.Context, *EnableUserRequest) (*EnableUserResponse, error)
	// DisableUser disables a user: every request of theirs fails until they're
	// enabled again.
	DisableUser(context.Context, *DisableUserRequest) (*DisableUserResponse, error)
	// PreviewUserDeletion is a read-only dry run of DeleteUser: what it would
	// block on, leave orphaned and remove. It fails closed, naming the step,
	// when any class can't be read.
	PreviewUserDeletion(context.Context, *PreviewUserDeletionRequest) (*PreviewUserDeletionResponse, error)
	// DeleteUser deletes a user: it disables the account, revokes its
	// sessions and its local credential, removes its category access rules in
	// core and drops its identity access rows. Policies it owns stay, without
	// an owner, for reassignment. The row is kept so history still names it.
	// The root admin can't be deleted, and an account holding pending
	// approvals is refused.
	DeleteUser(context.Context, *DeleteUserRequest) (*DeleteUserResponse, error)
	// PreviewAccountMerge is a read-only dry run of MergeAccounts: exactly
	// what would move from the source to the target, with warnings.
	PreviewAccountMerge(context.Context, *PreviewAccountMergeRequest) (*PreviewAccountMergeResponse, error)
	// MergeAccounts moves the source account's policies, access rules,
	// acknowledgements, pending workflow items and preferences to the target,
	// revokes the source's sessions, records one audit event naming both and
	// deletes the source, marked as merged into the target. Every step can be
	// resumed: run it again with the same idempotency key after a partial
	// failure. A root or site-admin source needs confirm_privileged.
	MergeAccounts(context.Context, *MergeAccountsRequest) (*MergeAccountsResponse, error)
	// GrantRole adds a role to a user.
	GrantRole(context.Context, *GrantRoleRequest) (*GrantRoleResponse, error)
	// RevokeRole removes a role from a user.
	RevokeRole(context.Context, *RevokeRoleRequest) (*RevokeRoleResponse, error)
	// CreateGroup creates a group, optionally under a parent.
	CreateGroup(context.Context, *CreateGroupRequest) (*CreateGroupResponse, error)
	// RenameGroup renames a group; its id stays.
	RenameGroup(context.Context, *RenameGroupRequest) (*RenameGroupResponse, error)
	// DeleteGroup deletes a group with no members and no subgroups.
	DeleteGroup(context.Context, *DeleteGroupRequest) (*DeleteGroupResponse, error)
	// AddUserToGroup adds a membership.
	AddUserToGroup(context.Context, *AddUserToGroupRequest) (*AddUserToGroupResponse, error)
	// RemoveUserFromGroup removes a membership.
	RemoveUserFromGroup(context.Context, *RemoveUserFromGroupRequest) (*RemoveUserFromGroupResponse, error)
	// GrantGroupManager lets a user manage one group's manual memberships
	// without site-admin. It doesn't let them create or rename groups, or pass
	// the grant on.
	GrantGroupManager(context.Context, *GrantGroupManagerRequest) (*GrantGroupManagerResponse, error)
	// RevokeGroupManager removes a group-manager grant.
	RevokeGroupManager(context.Context, *RevokeGroupManagerRequest) (*RevokeGroupManagerResponse, error)
	// SetGroupParent moves a group, or makes it a root group when
	// new_parent_id is empty. Cycles are refused.
	SetGroupParent(context.Context, *SetGroupParentRequest) (*SetGroupParentResponse, error)
	// BootstrapInitialAdmin creates the first admin, only while none exists.
	BootstrapInitialAdmin(context.Context, *BootstrapInitialAdminRequest) (*BootstrapInitialAdminResponse, error)
	// SetUserPolicyOverride sets a per-policy override; OVERRIDE_EFFECT_UNSPECIFIED
	// clears it.
	SetUserPolicyOverride(context.Context, *SetUserPolicyOverrideRequest) (*SetUserPolicyOverrideResponse, error)
	// RequestStepUpOtp emails a step-up code to the calling admin, to confirm
	// a high-risk action such as GrantRoot or RevokeRoot.
	RequestStepUpOtp(context.Context, *RequestStepUpOtpRequest) (*RequestStepUpOtpResponse, error)
	// GrantRoot makes another user a root admin as well; they also get
	// site-admin. Root only, refused during act-as, and the calling admin's
	// step-up code is checked first.
	GrantRoot(context.Context, *GrantRootRequest) (*GrantRootResponse, error)
	// RevokeRoot takes the root role from a user, who keeps site-admin. The
	// last root admin can't lose it. Same checks as GrantRoot.
	RevokeRoot(context.Context, *RevokeRootRequest) (*RevokeRootResponse, error)
	// Deprecated: Do not use.
	// TransferRoot is removed now that more than one user can hold the root
	// role: it always returns Unimplemented, naming GrantRoot and RevokeRoot.
	// Kept only so a caller still built against the old shape gets a clear
	// error instead of a broken RPC.
	TransferRoot(context.Context, *TransferRootRequest) (*TransferRootResponse, error)
	// RequestHardReset starts a two-person hard reset of a module: one root
	// admin asks, a different root admin approves. The request expires after
	// HARD_RESET_REQUEST_TTL. Root only, refused during act-as. One open
	// request per module.
	RequestHardReset(context.Context, *RequestHardResetRequest) (*RequestHardResetResponse, error)
	// ApproveHardReset approves a pending request. The requester can't approve
	// their own. The approval can be used once, within HARD_RESET_APPROVAL_TTL.
	ApproveHardReset(context.Context, *ApproveHardResetRequest) (*ApproveHardResetResponse, error)
	// CancelHardReset withdraws a pending or approved request. Only its
	// requester may cancel it.
	CancelHardReset(context.Context, *CancelHardResetRequest) (*CancelHardResetResponse, error)
	// ListHardResetRequests lists the hard reset requests, newest first. Root
	// only.
	ListHardResetRequests(context.Context, *ListHardResetRequestsRequest) (*ListHardResetRequestsResponse, error)
	// ConsumeHardReset redeems an approved request once, just before the
	// module's own service runs the reset. Only the module's service calls it,
	// as itself.
	ConsumeHardReset(context.Context, *ConsumeHardResetRequest) (*ConsumeHardResetResponse, error)
	// RevokeSession revokes one session.
	RevokeSession(context.Context, *RevokeSessionRequest) (*RevokeSessionResponse, error)
	// RevokeUserSessions revokes every session of a user.
	RevokeUserSessions(context.Context, *RevokeUserSessionsRequest) (*RevokeUserSessionsResponse, error)
	// ListUserSessions lists a user's sessions.
	ListUserSessions(context.Context, *ListUserSessionsRequest) (*ListUserSessionsResponse, error)
	// GrantPermission grants an individual permission (policy.read_sensitive).
	// Root only.
	GrantPermission(context.Context, *GrantPermissionRequest) (*GrantPermissionResponse, error)
	// RevokePermission removes an individual permission. Root only.
	RevokePermission(context.Context, *RevokePermissionRequest) (*RevokePermissionResponse, error)
	// BreakGlassReveal records a time-boxed, audited break-glass reveal of one
	// policy for the calling site-admin. A reason is required.
	BreakGlassReveal(context.Context, *BreakGlassRevealRequest) (*BreakGlassRevealResponse, error)
	// ActiveBreakGlass lists the policies the calling user holds an unexpired
	// break-glass grant for.
	ActiveBreakGlass(context.Context, *ActiveBreakGlassRequest) (*ActiveBreakGlassResponse, error)
	// CreateLocalUser creates a local account with a password in the sign-in
	// service.
	CreateLocalUser(context.Context, *CreateLocalUserRequest) (*CreateLocalUserResponse, error)
	// ResetUserPassword sets a local account's password.
	ResetUserPassword(context.Context, *ResetUserPasswordRequest) (*ResetUserPasswordResponse, error)
	// UpdateUserProfile changes another user's name and email.
	UpdateUserProfile(context.Context, *UpdateUserProfileRequest) (*UpdateUserProfileResponse, error)
	// CompleteOnboarding finishes the calling user's first-run onboarding.
	// Self-service. accept_terms must be true.
	CompleteOnboarding(context.Context, *CompleteOnboardingRequest) (*CompleteOnboardingResponse, error)
	// UpdateMyProfile changes the calling user's own name, time zone and
	// locale. Self-service; the display name is derived from the parts.
	UpdateMyProfile(context.Context, *UpdateMyProfileRequest) (*UpdateMyProfileResponse, error)
	// AdminListUserFactors lists a user's second factors, one per passkey,
	// each with the id the calls below take.
	AdminListUserFactors(context.Context, *AdminListUserFactorsRequest) (*AdminListUserFactorsResponse, error)
	// AdminRemoveUserFactor resets one of a user's factors so they can enrol
	// again: "totp" or a passkey's credential id. The email factor can't be
	// removed.
	AdminRemoveUserFactor(context.Context, *AdminRemoveUserFactorRequest) (*AdminRemoveUserFactorResponse, error)
	// AdminRenameUserFactor labels one of a user's factors. An empty label
	// clears it.
	AdminRenameUserFactor(context.Context, *AdminRenameUserFactorRequest) (*AdminRenameUserFactorResponse, error)
	mustEmbedUnimplementedIdentityAdminServiceServer()
}

